
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_r2scan01_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_r2scan01", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.884472460360464e+00, -4.785580961867112e+00, -4.646968119345446e+00, -4.454865352075517e+00, -4.192908175054848e+00, -3.843844221435759e+00, -3.393647861203528e+00, -2.838935129376897e+00, -2.196684855272025e+00, -1.503524977729371e+00, -8.521809629035207e-01, -6.160546471190439e-01, -6.300851872027431e-01, -5.314019881260225e-01, -3.624864811945278e-01, -1.981936585173190e-01, -7.962990366582645e-02, -2.154897441364420e-02, -3.074251077939663e-03, -1.501276762343395e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


